/* ============================================================
   Aventurs — Misiones
   v3.15.1: todos los cambios de las versiones (los "parches" seed-v39 a
   seed-v315) ya están aplicados acá. La historia está en CHANGELOG.md.
   ============================================================ */

(function (A) {
  'use strict';
  A.Seed = A.Seed || {};
  A.Seed.quests = [
    { id: 'mq1_humo', main: true, chapter: 1, giver: 'npc_guardia_pueblo', title: 'Humo sobre el bosque', offer: 'Anoche se vio humo sobre el Bosque Sombrío. Esta mañana encontramos árboles quemados... desde la copa para abajo. Andá a mirar qué pasa y volvé a contarme.', text: 'Tomas el guardia vio humo sobre el Bosque Sombrío. Explorá el bosque y volvé a contarle.', objectives: [{ type: 'explore', region: 'bosque_sombrio', count: 3 }], turnIn: true, done: 'Árboles quemados desde arriba y olor a azufre... Esto no lo hizo ningún incendio común.', reward: { xp: 20, coins: 20 }, next: 'mq1b_tumba' },
    { id: 'mq1b_tumba', main: true, chapter: 2, giver: 'npc_guardia_pueblo', requires: 'mq1_humo', title: 'Garras en la tumba', offer: 'Hay más. Anoche alguien abrió la cripta grande del Cementerio: la reja está doblada y la piedra tiene marcas de garras quemadas. Los muertos andan inquietos desde entonces. Fijate qué buscaban.', text: 'Alguien abrió la cripta grande del Cementerio y dejó marcas de garras quemadas. Explorá el Cementerio, calmá a los muertos que se levantaron y volvé con Tomas.', objectives: [{ type: 'explore', region: 'cementerio', count: 2 }, { type: 'kill', enemy: ['esqueleto', 'zombi'], count: 2 }], turnIn: true, done: 'Entre los huesos revueltos encontraste una escama negra, grande como tu mano y tibia todavía. Tomas no la quiere ni tocar: "Eso no es de ningún bicho de por acá."', reward: { xp: 20, coins: 25, items: [['pocion_curacion_menor', 1]] }, next: 'mq1c_aldea' },
    { id: 'mq1c_aldea', main: true, chapter: 3, giver: 'npc_guardia_pueblo', requires: 'mq1b_tumba', minLevel: 2, title: 'La aldea de los mineros', offer: 'Llevale esa escama a Grimbold, el herrero de Piedrahonda. Los enanos conocen cada metal y cada bicho que vive debajo de la tierra. Tomá el Camino Real hacia el norte.', text: 'Tomas quiere que Grimbold, el herrero de Piedrahonda, vea la escama negra. Llegá a la aldea y hablá con él.', objectives: [{ type: 'visit', region: 'aldea_piedrahonda' }, { type: 'talk', npc: 'npc_herrero_piedrahonda' }], done: 'Grimbold pesa la escama en la mano y deja de sonreír: "Dragón. Y de los viejos."', reward: { xp: 20, coins: 15 }, next: 'mq1d_kobolds' },
    { id: 'mq1d_kobolds', main: true, chapter: 4, giver: 'npc_herrero_piedrahonda', requires: 'mq1c_aldea', minLevel: 2, title: 'Cantos en las minas', offer: 'Desde hace una semana los kobolds de las Minas Olvidadas cantan de noche. Los kobolds les rezan a los dragones, ¿sabías? Si uno despertó, lo sienten. Bajá, callalos un poco y traeme el ídolo al que le cantan.', text: 'Los kobolds de las Minas Olvidadas le cantan a un dragón. Explorá las minas y quitales el ídolo para que lo vea Grimbold.', objectives: [{ type: 'explore', region: 'minas_olvidadas', count: 2 }, { type: 'collect', item: 'idolo_kobold', count: 1, from: ['kobold'], text: 'Quitale el ídolo a los kobolds' }], turnIn: true, done: 'Grimbold da vuelta el ídolo: un dragón negro sobre un barco en llamas. "Esto pasó en el mar. Andá al Puerto: Irena, la capitana, sabe todo lo que pasa en el agua."', reward: { xp: 30, coins: 30 }, next: 'mq2_puerto' },
    { id: 'mq2_puerto', main: true, chapter: 5, giver: 'npc_herrero_piedrahonda', requires: 'mq1d_kobolds', minLevel: 3, title: 'El camino del este', offer: 'Seguí el Camino Real hasta el Puerto y buscá a Irena, la capitana. Si alguien vio un barco quemarse, fue ella.', text: 'El ídolo de los kobolds muestra un barco en llamas. Viajá al Puerto y hablá con Irena, la capitana.', objectives: [{ type: 'visit', region: 'puerto' }, { type: 'talk', npc: 'npc_capitana_puerto' }], done: 'Irena te recibe en el muelle: "¿Vos también la viste? Entonces no estoy loca."', reward: { xp: 30, coins: 30 }, next: 'mq2b_bitacora' },
    { id: 'mq2b_bitacora', main: true, chapter: 6, giver: 'npc_capitana_puerto', requires: 'mq2_puerto', minLevel: 3, title: 'Lo que trajo la marea', offer: 'Hace tres noches una llamarada cayó del cielo sobre La Gaviota, un barco mercante, frente a la Costa de los Naufragios. No quedó nadie. Los piratas ya están saqueando los restos. Si recuperás la bitácora del capitán, vamos a saber qué vio.', text: 'Un barco ardió frente a la Costa de los Naufragios. Explorá la costa y recuperá la bitácora del capitán: la tienen los piratas... o el mar.', objectives: [{ type: 'explore', region: 'costa_naufragios', count: 2 }, { type: 'collect', item: 'bitacora_quemada', count: 1, from: ['grumete_pirata', 'contrabandista', 'pirata', 'ahogado'], text: 'Recuperá la bitácora (piratas y ahogados de la costa)' }], turnIn: true, done: 'Irena lee la última página en voz baja: "Fuego desde el cielo. Alas negras. Iba hacia las montañas." Se queda un rato mirando el mar.', reward: { xp: 50, coins: 60 }, next: 'mq3_sabio' },
    { id: 'mq3_sabio', main: true, chapter: 7, giver: 'npc_capitana_puerto', requires: 'mq2b_bitacora', minLevel: 4, title: 'Fuego sobre el mar', offer: 'Alas negras que vuelan hacia las montañas... Mis marineros dicen que era un dragón. Velrith, el sabio de la torre, sabe de estas cosas. La Torre del Mago está al este del Puerto.', text: 'La bitácora habla de alas negras que volaban hacia las montañas. Preguntale al sabio Velrith en la Torre del Mago.', objectives: [{ type: 'talk', npc: 'npc_sabio_torre' }], done: 'Velrith cierra el libro despacio: "Un dragón despertó. Y no está solo."', reward: { xp: 40, coins: 30 }, next: 'mq4_diablillos' },
    { id: 'mq4_diablillos', main: true, chapter: 8, giver: 'npc_sabio_torre', requires: 'mq3_sabio', minLevel: 4, title: 'Los sirvientes del fuego', offer: 'Los diablillos de las Montañas se volvieron osados: sirven a algo más grande. Derrotá a tres y traeme una de sus colas. Quiero ver qué fuego los alimenta.', text: 'Velrith cree que los diablillos de las Montañas sirven al dragón. Derrotá tres y llevale una cola.', objectives: [{ type: 'kill', enemy: 'diablillo', count: 3 }, { type: 'collect', item: 'mat_cola_diablillo', count: 1 }], turnIn: true, done: 'La cola todavía humea. "Fuego de dragón", murmura Velrith. "Y no de cualquiera: de uno que ya quemó este reino una vez."', reward: { xp: 110, coins: 80, items: [['pocion_curacion', 1]] }, next: 'mq4b_tomo' },
    { id: 'mq4b_tomo', main: true, chapter: 9, giver: 'npc_sabio_torre', requires: 'mq4_diablillos', minLevel: 5, title: 'La biblioteca de Antorcha', offer: 'Hace trescientos años un dragón negro quemó la fortaleza de Antorcha, y alguien logró dormirlo. En su biblioteca había un tomo que contaba cómo. Hoy las ruinas están llenas de drows y magos oscuros. Traeme ese tomo.', text: 'En las Ruinas de Antorcha había un tomo que cuenta cómo se durmió al dragón negro. Explorá las ruinas y recuperalo: lo tiene alguno de los que viven ahí.', objectives: [{ type: 'explore', region: 'ruinas_antorcha', count: 2 }, { type: 'collect', item: 'tomo_antorcha', count: 1, from: ['drow', 'banshee', 'mago_oscuro', 'nigromante'], text: 'Recuperá el tomo (drows, banshees y magos de las ruinas)' }], turnIn: true, done: 'Velrith pasa las hojas chamuscadas con cuidado. "Lo durmió una druida, con la savia del Gran Roble. Si todavía quedan druidas, van a saber qué pasó."', reward: { xp: 140, coins: 120 }, next: 'mq4c_roble' },
    { id: 'mq4c_roble', main: true, chapter: 10, giver: 'npc_sabio_torre', requires: 'mq4b_tomo', minLevel: 5, title: 'La savia del Gran Roble', offer: 'Los druidas viven en el Santuario del Roble, del otro lado del Bosque de los Sueños. Se entra por el Bosque Sombrío. Cruzalo sin dormirte y hablá con quien cuide el roble.', text: 'Al dragón negro lo durmió una druida. Cruzá el Bosque de los Sueños hasta el Santuario del Roble y hablá con la druida.', objectives: [{ type: 'visit', region: 'santuario_roble' }, { type: 'talk', npc: 'npc_druida_santuario' }], done: 'Sylveth te escucha sin interrumpir. "El sueño de un dragón no se rompe solo. Alguien lo despertó, y a propósito."', reward: { xp: 60, coins: 40 }, next: 'mq4d_sueno' },
    { id: 'mq4d_sueno', main: true, chapter: 11, giver: 'npc_druida_santuario', requires: 'mq4c_roble', minLevel: 6, title: 'Lo que sueña el bosque', offer: 'Este bosque guarda todo lo que se sueña cerca de él. Traeme dos flores del sueño y derrotá a una pesadilla: con su sombra y las flores preparo una infusión para ver quién despertó al dragón.', text: 'Sylveth necesita dos flores del sueño y que derrotes una pesadilla del Bosque de los Sueños para ver quién despertó al dragón.', objectives: [{ type: 'collect', item: 'flor_sueno', count: 2, from: ['hada_traviesa', 'polilla_onirica'] }, { type: 'kill', enemy: 'pesadilla', count: 1 }], turnIn: true, done: 'Sylveth bebe la infusión y cierra los ojos. "Veo una túnica gris como la ceniza y una voz que le canta al dragón en una lengua muerta. Para seguirla vas a tener que cruzar el fuego."', reward: { xp: 180, coins: 100, items: [['pocion_mana', 1]] }, next: 'mq5_amuleto' },
    { id: 'mq5_amuleto', main: true, chapter: 12, giver: 'npc_sabio_torre', requires: 'mq4d_sueno', auto: true, title: 'El amuleto de fuego', offer: 'Nadie entra al volcán sin un Amuleto de fuego. Hace falta una gema ígnea y dos obsidianas.', text: 'Para entrar al Volcán necesitás un Amuleto de fuego: una gema ígnea (Montañas) y dos obsidianas (Cuevas Ancestrales). Druss, el herrero del Puerto, sabe forjarlo.', objectives: [{ type: 'have', item: 'amuleto_fuego' }], done: 'El amuleto late tibio contra tu pecho. El calor ya no te asusta.', reward: { xp: 180 }, next: 'mq5b_ceniza' },
    { id: 'mq5b_ceniza', main: true, chapter: 13, giver: 'npc_druida_santuario', requires: 'mq5_amuleto', auto: true, title: 'Ceniza en Velmora', offer: 'Los de túnica gris compran huesos y sangre en Velmora.', text: 'Dicen que los de túnica gris compran huesos y sangre en Velmora. La condesa Ilyana sabe quién compra qué en su ciudad: andá a verla.', objectives: [{ type: 'visit', region: 'velmora' }, { type: 'talk', npc: 'npc_condesa_velmora' }], done: 'La condesa sonríe sin mostrar los dientes. "Los encapuchados. Me compran lo que nadie quiere y no pagan impuestos. Ayudame y te digo quiénes son."', reward: { xp: 100, coins: 50 }, next: 'mq5c_sellos' },
    { id: 'mq5c_sellos', main: true, chapter: 14, giver: 'npc_condesa_velmora', requires: 'mq5b_ceniza', minLevel: 7, title: 'Los sellos de las catacumbas', offer: 'Cada luna, los encapuchados bajan a las Catacumbas y rompen los sellos de las tumbas viejas. Los muertos que despiertan llevan esos sellos encima. Traeme dos y te digo a quién sirven.', text: 'Los encapuchados rompen los sellos de las Catacumbas. Explorá las catacumbas y conseguí dos sellos de ceniza para la condesa Ilyana.', objectives: [{ type: 'explore', region: 'catacumbas', count: 2 }, { type: 'collect', item: 'sello_ceniza', count: 2, from: ['espectro', 'aparicion', 'cab_muerte', 'medusa'], text: 'Conseguí sellos de ceniza (los muertos de las catacumbas)' }], turnIn: true, done: 'La condesa raspa la ceniza de un sello: debajo hay un nombre grabado. "Morvaith. Un lich que se hace llamar el Heraldo del Dragón. Él lo despertó. Si el dragón vuela, él manda." Te da una cajita de hueso: "Su filacteria. Con esto y tres cráneos, lo despertás en su cripta."', reward: { xp: 330, coins: 300, items: [['filacteria_rota', 1]] }, next: 'mq6_volcan' },
    { id: 'mq6_volcan', main: true, chapter: 15, giver: 'npc_sabio_torre', requires: 'mq5c_sellos', auto: true, title: 'El corazón del volcán', offer: 'Con el amuleto podés entrar al Volcán.', text: 'Con el amuleto puesto, llegá al Volcán. Desde ahí se ve el camino al nido.', objectives: [{ type: 'visit', region: 'volcan' }], done: 'El aire tiembla de calor. Allá arriba, entre el humo, algo grande se mueve.', reward: { xp: 220 }, next: 'mq7_guardian' },
    { id: 'mq7_guardian', main: true, chapter: 16, giver: 'npc_sabio_torre', requires: 'mq6_volcan', auto: true, title: 'El guardián del cráter', offer: 'Un dragón joven cuida el paso al nido.', text: 'Un dragón joven cuida el paso hacia el Nido de Dragones. Derrotalo.', objectives: [{ type: 'kill', enemy: 'dragon_joven', count: 1 }], done: 'El dragón joven cae entre las rocas. El paso al nido queda libre.', reward: { xp: 450, coins: 300 }, next: 'mq7b_heraldo' },
    { id: 'mq7b_heraldo', main: true, chapter: 17, giver: 'npc_sabio_torre', requires: 'mq7_guardian', auto: true, title: 'El Heraldo de la Ceniza', offer: 'Morvaith duerme en su cripta, debajo de las Catacumbas.', text: 'Morvaith, el lich que despertó al dragón, duerme en la Cripta del Lich, debajo de las Catacumbas. Despertalo en el altar con su filacteria y tres cráneos. Sin su heraldo, el dragón queda solo.', objectives: [{ type: 'kill', enemy: 'lich', count: 1, text: 'Derrotá a Morvaith, el lich' }], done: 'El lich se deshace en ceniza gris. Lejos, un rugido sacude las montañas: el dragón sabe que ahora está solo.', reward: { xp: 700, coins: 500 }, next: 'mq8_sombra' },
    { id: 'mq8_sombra', main: true, chapter: 18, giver: 'npc_sabio_torre', requires: 'mq7b_heraldo', auto: true, title: 'La sombra del dragón', offer: 'El dragón que despertó Morvaith es Alamuerte, el más fuerte de todos los dragones. Espera en su trono, en los Picos del Dragón (arriba del Nido de Dragones): antes de ir, hacete fuerte en las Tierras Altas.', text: 'Alamuerte espera en su trono, en los Picos del Dragón (es para nivel 20: se llega desde el Bosque Petrificado). Terminá con la sombra que cubre el reino.', objectives: [{ type: 'kill', enemy: 'alamuerte', count: 1, text: 'Derrotá a Alamuerte' }], done: 'Las placas de Alamuerte se apagan una por una. La sombra que cubría el reino se disipa y tu nombre se va a cantar en todas las tabernas.', reward: { xp: 4000, coins: 25000 } },
    { id: 'sq_colmillos', giver: 'npc_mercader_pueblo', title: 'Dientes de lobo', offer: 'Traeme tres dientes de lobo y te pago bien. Los alquimistas de la ciudad me los sacan de las manos.', text: 'Borgan, el mercader, te paga por tres dientes de lobo. Los lobos andan por el Bosque Sombrío y el Camino Real.', objectives: [{ type: 'collect', item: 'mat_diente_lobo', count: 3 }], turnIn: true, done: '"¡Lindos dientes! Tomá, te los ganaste."', reward: { coins: 45, items: [['pocion_curacion_menor', 2]] } },
    { id: 'sq_ratas', giver: 'npc_tabernero_pueblo', title: 'Ratas en el sótano', offer: 'Las ratas se están comiendo mis quesos. Vienen del bosque y del cementerio. Si matás cuatro, la próxima comida va por la casa.', text: 'Maela, la tabernera, quiere que mates cuatro ratas (comunes o gigantes).', objectives: [{ type: 'kill', enemy: ['rata', 'rata_gigante'], count: 4 }], turnIn: true, done: '"¡Por fin silencio en el sótano!" Maela te sirve un plato bien cargado.', reward: { coins: 25, xp: 10, items: [['carne_seca', 2], ['queso', 1]] } },
    { id: 'sq_zorros', giver: 'npc_tabernero_pueblo', title: 'Zorros en el gallinero', offer: 'Los zorros del Bosque Sombrío se me llevan las gallinas de a una. Si espantás a tres, te pago en monedas y en huevos, que todavía me quedan algunos.', text: 'Maela quiere que derrotes a tres zorros del Bosque Sombrío.', objectives: [{ type: 'kill', enemy: 'zorro', count: 3 }], turnIn: true, done: '"¡Mis gallinas te lo agradecen!" Maela te envuelve media docena de huevos.', reward: { coins: 30, xp: 10, items: [['huevos', 2]] } },
    { id: 'sq_perros', giver: 'npc_mercader_pueblo', title: 'Perros en los llanos', offer: 'Una jauría de perros salvajes asusta a mis mulas en los Llanos del Alba. Sin mulas no hay mercadería. ¿Te encargás de tres?', text: 'Borgan quiere que derrotes a tres perros salvajes en los Llanos del Alba.', objectives: [{ type: 'kill', enemy: 'perro_salvaje', count: 3 }], turnIn: true, done: '"Ahora mis mulas van a poder pasar tranquilas."', reward: { coins: 35, xp: 10, items: [['pocion_curacion_menor', 1]] } },
    { id: 'sq_huesos', giver: 'npc_guardia_pueblo', minLevel: 2, title: 'Huesos inquietos', offer: 'De noche se escuchan huesos que caminan en el cementerio. Derrotá a tres esqueletos y la gente va a dormir tranquila.', text: 'Tomas el guardia te pide derrotar tres esqueletos en el Cementerio.', objectives: [{ type: 'kill', enemy: 'esqueleto', count: 3 }], turnIn: true, done: '"Gracias. Esta noche voy a hacer la ronda sin temblar."', reward: { coins: 50, xp: 15 } },
    { id: 'sq_sapos', giver: 'npc_tabernero_pueblo', minLevel: 3, title: 'Sopa de pantano', offer: 'Mi abuela hacía una sopa de sapo del pantano que te dejaba como nuevo. Traeme dos pieles de anfibio y la probamos.', text: 'Maela necesita dos pieles de anfibio. Los sapos gigantes del Pantano las tienen.', objectives: [{ type: 'collect', item: 'piel_anfibio', count: 2 }], turnIn: true, done: 'La sopa huele raro, pero cae de maravilla.', reward: { coins: 60, xp: 20, items: [['sopa', 2]] } },
    { id: 'sq_minas', giver: 'npc_herrero_piedrahonda', minLevel: 2, title: 'Kobolds en las minas', offer: 'Los kobolds se metieron en las Minas Olvidadas y no me dejan sacar mineral. Sacame de encima a cuatro y te forjo algo que valga la pena.', text: 'Grimbold quiere que derrotes a cuatro kobolds en las Minas Olvidadas.', objectives: [{ type: 'kill', enemy: 'kobold', count: 4 }], turnIn: true, done: '"¡Ja! Ya se escuchan los picos otra vez." Grimbold te da un martillo recién templado.', reward: { coins: 40, xp: 15, items: [['martillo_enano', 1]] } },
    { id: 'sq_cuarzo', giver: 'npc_tabernera_piedrahonda', minLevel: 2, title: 'Cuarzo para las lámparas', offer: 'Las lámparas de la taberna funcionan con cuarzo y se me terminó. En las minas hay de sobra. Traeme dos trozos.', text: 'Brenna necesita dos fragmentos de cuarzo para las lámparas de la taberna.', objectives: [{ type: 'collect', item: 'fragmento_cuarzo', count: 2 }], turnIn: true, done: '"¡Ahora sí, luz!" Brenna te sirve una cena para el camino.', reward: { coins: 35, xp: 10, items: [['carne_seca', 2], ['pan', 2]] } },
    { id: 'sq_escarabajos', giver: 'npc_herrero_piedrahonda', minLevel: 3, title: 'Escarabajos en las vetas', offer: 'Unos escarabajos del tamaño de un perro se comen las vetas de hierro de las minas. Así no hay forja que aguante. Aplastá a tres.', text: 'Grimbold quiere que derrotes a tres escarabajos mineros en las Minas Olvidadas.', objectives: [{ type: 'kill', enemy: 'escarabajo_minero', count: 3 }], turnIn: true, done: '"¡Eso! Tomá, de la última veta que me dejaron."', reward: { coins: 70, xp: 25, items: [['mineral_hierro', 2]] } },
    { id: 'sq_bandidos', giver: 'npc_capitana_puerto', minLevel: 3, title: 'Bandidos del camino', offer: 'Mis cargamentos no llegan: los bandidos del Camino Real los asaltan. Derrotá a tres y te pago como a un marinero.', text: 'Irena te paga por derrotar a tres bandidos del Camino Real.', objectives: [{ type: 'kill', enemy: 'bandido', count: 3 }], turnIn: true, done: '"Así me gusta. El mar y el camino, limpios."', reward: { coins: 120, xp: 30 } },
    { id: 'sq_perlas', giver: 'npc_capitana_puerto', minLevel: 3, title: 'Perlas para un collar', offer: 'Mi hija cumple años. Quiero regalarle un collar, pero las perlas buenas están en la costa y en alta mar. Traeme tres.', text: 'Irena quiere tres perlas pequeñas. Aparecen en la costa y en alta mar.', objectives: [{ type: 'collect', item: 'perla_pequeña', count: 3 }], turnIn: true, done: 'Irena sonríe por primera vez: "Va a estar feliz."', reward: { coins: 220, xp: 20 } },
    { id: 'sq_ahogados', giver: 'npc_capitana_puerto', minLevel: 4, title: 'Los que el mar devuelve', offer: 'De noche, los ahogados de la Costa de los Naufragios salen del agua y caminan hacia el Puerto. Algunos eran mis marineros. Dales descanso: con tres alcanza para que los demás entiendan.', text: 'Irena te pide derrotar a tres ahogados en la Costa de los Naufragios.', objectives: [{ type: 'kill', enemy: 'ahogado', count: 3 }], turnIn: true, done: 'Irena se saca el sombrero un momento. "Gracias. Ahora sí descansan."', reward: { coins: 120, xp: 40, items: [['pocion_curacion', 1]] } },
    { id: 'sq_hierro', giver: 'npc_herrero_puerto', minLevel: 4, title: 'Hierro para la forja', offer: 'Se me terminó el hierro y tengo encargos atrasados. Traeme cuatro trozos de mineral de hierro de las Montañas o las Cuevas.', text: 'Druss, el herrero, necesita cuatro trozos de mineral de hierro.', objectives: [{ type: 'collect', item: 'mineral_hierro', count: 4 }], turnIn: true, done: '"Buen hierro. Con esto saco una espada por día."', reward: { coins: 140, xp: 40, items: [['mat_acero', 1]] } },
    { id: 'sq_orcos', giver: 'npc_herrero_puerto', minLevel: 4, title: 'Orcos en las colinas', offer: 'Los orcos de las Colinas Rotas emboscan a los carros que me traen carbón. Si derrotás a tres, te hago un descuento de amigo... bueno, te pago.', text: 'Druss te paga por derrotar a tres orcos de las Colinas Rotas.', objectives: [{ type: 'kill', enemy: 'orco', count: 3 }], turnIn: true, done: '"Ya llegó el carbón. Que se note en el acero."', reward: { coins: 130, xp: 40 } },
    { id: 'sq_troll', giver: 'npc_herrero_puerto', minLevel: 6, title: 'Sangre de troll', offer: 'Dicen que el acero templado en sangre de troll no se rompe nunca. Quiero probarlo. Los trolls viven en las Cuevas Ancestrales... y se curan solos, así que pegá fuerte.', text: 'Druss quiere sangre de troll para templar acero. Los trolls viven en las Cuevas Ancestrales.', objectives: [{ type: 'kill', enemy: 'troll', count: 1 }, { type: 'collect', item: 'mat_sangre_troll', count: 1 }], turnIn: true, done: 'Druss hunde una hoja al rojo en la sangre verde. El vapor huele horrible. "¡Perfecta!"', reward: { coins: 220, xp: 110, items: [['mat_acero', 2]] } },
    { id: 'sq_polvo', giver: 'npc_sabio_torre', minLevel: 4, title: 'Polvo de estrellas', offer: 'Para mis estudios necesito polvo arcano. Se junta en el aire alrededor de esta torre, si sabés mirar. Traeme tres puñados.', text: 'Velrith quiere tres puñados de polvo arcano. Se encuentra viajando cerca de la Torre.', objectives: [{ type: 'collect', item: 'polvo_arcano', count: 3 }], turnIn: true, done: '"Excelente. La magia agradece a quien la junta con paciencia."', reward: { xp: 40, items: [['pocion_mana', 2]] } },
    { id: 'sq_momias', giver: 'npc_sabio_torre', minLevel: 5, title: 'Reliquias del desierto', offer: 'Las momias del Desierto custodian reliquias de un reino que ni yo conozco. Derrotá a dos y traeme una reliquia: quiero leer lo que tiene grabado.', text: 'Velrith quiere una reliquia olvidada del Desierto. Las momias las cuidan.', objectives: [{ type: 'kill', enemy: 'momia', count: 2 }, { type: 'collect', item: 'reliquia_olvidada', count: 1 }], turnIn: true, done: '"Fascinante. Un reino entero que se tragó la arena." Velrith ya no te mira: está leyendo.', reward: { coins: 150, xp: 60 } },
    { id: 'sq_hidra', giver: 'npc_sabio_torre', minLevel: 13, title: 'El colmillo de la hidra', offer: 'Para un hechizo que estoy estudiando necesito un colmillo de hidra. La hidra vive en su lago, en el fondo de la Ciénaga Primordial. Tiene tres cabezas y muerde con las tres, así que cortá rápido.', text: 'Velrith necesita un colmillo de la hidra del Lago de la Hidra (en la Ciénaga Primordial). Es de nivel 14.', objectives: [{ type: 'kill', enemy: 'hidra', count: 1, text: 'Derrotá a la hidra' }, { type: 'collect', item: 'mat_colmillo_hidra', count: 1 }], turnIn: true, done: 'Velrith guarda el colmillo en una caja de plomo. "No lo toques. Nunca."', reward: { coins: 3500, xp: 450, items: [['pocion_mana_suprema', 2]] } },
    { id: 'sq_capitan', giver: 'npc_tabernero_calavera', minLevel: 5, title: 'La cabeza del capitán', offer: 'Hay un capitán en el Mar de las Calaveras que no le paga a nadie, ni siquiera a mí. Hundilo y te pago el doble de lo que él debe.', text: 'Tuerto Salvo paga por derrotar al capitán pirata del Mar de las Calaveras.', objectives: [{ type: 'kill', enemy: 'capitan_pirata', count: 1 }], turnIn: true, done: '"¡Por fin! Esta noche invita la casa." Tuerto Salvo cuenta los doblones dos veces.', reward: { coins: 260, xp: 70 } },
    { id: 'sq_ron', giver: 'npc_contrabandista_calavera', minLevel: 5, title: 'Ron para el puerto', offer: 'Los piratas de la costa esconden ron del bueno. Traeme cuatro botellas y nadie se entera.', text: 'Mara compra cuatro botellas de ron añejo. Los piratas de la costa las llevan encima.', objectives: [{ type: 'collect', item: 'ron_anejo', count: 4 }], turnIn: true, done: 'Mara guarda las botellas sin mirarlas y te pasa una bolsa pesada.', reward: { coins: 140, xp: 40 } },
    { id: 'sq_monedas', giver: 'npc_contrabandista_calavera', minLevel: 5, title: 'Monedas de otro reino', offer: 'Compro monedas antiguas. No pregunto de dónde salen. Los grumetes de la costa y las momias del desierto las llevan encima. Tres, y hablamos de precio.', text: 'Mara compra tres monedas antiguas. Las llevan los grumetes piratas y las momias.', objectives: [{ type: 'collect', item: 'moneda_antigua', count: 3 }], turnIn: true, done: 'Mara muerde cada moneda antes de pagarte. "Auténticas. Un placer."', reward: { coins: 220, xp: 40 } },
    { id: 'sq_tiburones', giver: 'npc_tabernero_calavera', minLevel: 6, title: 'Aletas en el agua', offer: 'Los tiburones se están comiendo a mis clientes... bueno, a los que se caen al agua borrachos. Igual es malo para el negocio. Bajá a tres.', text: 'Tuerto Salvo paga por derrotar a tres tiburones en el Mar de las Calaveras o en Alta Mar.', objectives: [{ type: 'kill', enemy: 'tiburon', count: 3 }], turnIn: true, done: '"¡A la salud de los que no se comieron!" Tuerto Salvo te sirve un vaso y te pasa una bolsa.', reward: { coins: 250, xp: 100 } },
    { id: 'sq_kraken', giver: 'npc_tabernero_calavera', minLevel: 9, title: 'El monstruo del abismo', offer: 'Hay un kraken en un remolino al lado del Abismo Marino que hundió más barcos que todos los piratas juntos. Primero vas a tener que cortarle los tentáculos. El que lo mate no paga nunca más en esta taberna. Y encima le doy esto.', text: 'Tuerto Salvo ofrece una fortuna por derrotar al kraken del Remolino del Kraken (al lado del Abismo Marino).', objectives: [{ type: 'kill', enemy: 'kraken', count: 1, text: 'Derrotá al kraken' }], turnIn: true, done: 'En Puerto Calavera no se habla de otra cosa. Tuerto Salvo cumple: te paga y te sirve la primera de muchas.', reward: { coins: 1500, xp: 200, items: [['elixir_vida', 1]] } },
    { id: 'sq_pesadillas', giver: 'npc_druida_santuario', minLevel: 5, title: 'Sueños rotos', offer: 'El Bosque de los Sueños tiene pesadillas que caminan. Si derrotás a tres, el bosque va a poder descansar.', text: 'Sylveth la druida te pide derrotar tres pesadillas en el Bosque de los Sueños.', objectives: [{ type: 'kill', enemy: 'pesadilla', count: 3 }], turnIn: true, done: 'Sylveth cierra los ojos y sonríe: "Ya duerme tranquilo."', reward: { xp: 70, items: [['pocion_mana', 2], ['pocion_curacion', 1]] } },
    { id: 'sq_huargos', giver: 'npc_druida_santuario', minLevel: 6, title: 'Aullidos entre los árboles', offer: 'Los huargos del Bosque de los Susurros bajaron hasta el borde del santuario. Cazan a los ciervos de luz. Si derrotás a tres, la manada se va a alejar.', text: 'Sylveth te pide derrotar a tres huargos en el Bosque de los Susurros.', objectives: [{ type: 'kill', enemy: 'huargo', count: 3 }], turnIn: true, done: '"Los ciervos ya vuelven a beber del arroyo. Gracias."', reward: { xp: 100, items: [['pocion_curacion', 2]] } },
    { id: 'sq_bruja', giver: 'npc_druida_santuario', minLevel: 7, title: 'La bruja del bosque', offer: 'Una bruja se instaló en el Bosque de los Susurros y les enseña a los árboles a odiar. Eso no se cura con savia. Hay que sacarla.', text: 'Sylveth quiere que derrotes a la bruja del Bosque de los Susurros.', objectives: [{ type: 'kill', enemy: 'bruja', count: 1, text: 'Derrotá a la bruja del bosque' }], turnIn: true, done: 'Los árboles dejan de susurrar. Sylveth apoya la mano en la corteza del roble y respira hondo.', reward: { xp: 150, items: [['pocion_mana_mayor', 1]] } },
    { id: 'sq_bestias', giver: 'npc_condesa_velmora', minLevel: 7, title: 'Sangre salvaje', offer: 'Las bestias del Jardín Carmesí nos avergüenzan. Cazalas por nosotros: tres alcanzan para que entiendan el mensaje.', text: 'La condesa Ilyana quiere que derrotes a tres bestias de sangre en el Jardín Carmesí.', objectives: [{ type: 'kill', enemy: 'bestia_sangre', count: 3 }], turnIn: true, done: '"Eficiente. Me gusta." La condesa deja caer un saco de oro sobre la mesa.', reward: { coins: 420, xp: 160 } },
    { id: 'sq_flores', giver: 'npc_boticaria_velmora', minLevel: 7, title: 'Flores entre tumbas', offer: 'La flor carmesí solo crece en el Jardín. Traeme tres y te pago en sangre... embotellada, claro.', text: 'Orsolya la boticaria quiere tres flores carmesí del Jardín Carmesí.', objectives: [{ type: 'collect', item: 'rosa_carmesi', count: 3 }], turnIn: true, done: 'Orsolya huele las flores y se le iluminan los ojos.', reward: { coins: 150, xp: 120, items: [['vial_sangre', 2]] } },
    { id: 'sq_senor', giver: 'npc_condesa_velmora', minLevel: 8, title: 'El señor de la noche', offer: 'En el castillo de la colina vive un vampiro que se cree dueño de Velmora. Es viejo, rico y muy maleducado. Quiero que deje de existir.', text: 'La condesa Ilyana quiere que derrotes al Señor vampiro del Castillo de Velmora.', objectives: [{ type: 'kill', enemy: 'senor_vampiro', count: 1, text: 'Derrotá al Señor vampiro' }], turnIn: true, done: '"Por fin un poco de paz en mi jardín." La condesa te entrega un cofre que pesa más de lo que parece.', reward: { coins: 900, xp: 180 } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_humano', race: 'humano', minLevel: 9, giver: 'npc_maestro_humano', title: 'La prueba del duelista', offer: 'Para la Resonancia arcana tenés que ganar un duelo de verdad. Hay caballeros de la muerte en la Fortaleza Caída y en las Catacumbas: derrotá a uno y volvé.', text: 'Aldric quiere que derrotes a un caballero de la muerte (Fortaleza Caída o Catacumbas) y vuelvas a la Torre del Mago.', objectives: [{ type: 'kill', enemy: 'cab_muerte', count: 1, text: 'Derrotá a un caballero de la muerte' }], done: 'Ganaste el duelo. Ahora tu arma va a resonar con tu magia.', reward: { xp: 300, learn: 'resonancia_arcana' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_angel', race: 'angel', minLevel: 9, giver: 'npc_maestra_angel', title: 'Almas en pena', offer: 'En el Fondo del Volcán hay almas condenadas que sufren sin descanso. Liberá a cuatro y volvé: así vas a aprender a levantar un santuario.', text: 'Sor Celestine quiere que liberes a cuatro almas condenadas en el Fondo del Volcán.', objectives: [{ type: 'kill', enemy: 'alma_condenada', count: 4, text: 'Liberá almas condenadas' }], done: 'Las almas descansan. Ahora sabés dónde nace un santuario.', reward: { xp: 300, learn: 'santuario_luminoso' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_enano', race: 'enano', minLevel: 9, giver: 'npc_maestro_enano', title: 'La prueba de piedra', offer: 'Una fortaleza ancestral se gana aguantando. En las Cuevas Ancestrales hay gólems: derrotá a dos sin dar un paso atrás.', text: 'Borin quiere que derrotes a dos gólems en las Cuevas Ancestrales.', objectives: [{ type: 'kill', enemy: 'golem', count: 2, text: 'Derrotá gólems' }], done: 'Aguantaste como la piedra. Sos una fortaleza.', reward: { xp: 300, learn: 'fortaleza_ancestral' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_goliat', race: 'goliat', minLevel: 9, giver: 'npc_maestra_goliat', title: 'Más grande que vos', offer: 'Para partir el suelo tenés que vencer a alguien más grande que vos. En la Pradera de los Cíclopes hay de sobra: derrotá a dos.', text: 'Kaya quiere que derrotes a dos cíclopes en la Pradera de los Cíclopes.', objectives: [{ type: 'kill', enemy: 'ciclope', count: 2, text: 'Derrotá cíclopes' }], done: 'Los gigantes cayeron. Ahora el suelo te va a obedecer.', reward: { xp: 300, learn: 'ruptura_terreno' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_draconido', race: 'draconido', minLevel: 9, giver: 'npc_maestro_draconido', title: 'La sangre llama', offer: 'Tus primos salvajes andan por el Volcán y el Nido de Dragones. Derrotá a tres dracónidos salvajes y tu furia va a despertar.', text: 'Vharax quiere que derrotes a tres dracónidos salvajes (Volcán o Nido de Dragones).', objectives: [{ type: 'kill', enemy: 'draconido_salvaje', count: 3, text: 'Derrotá dracónidos salvajes' }], done: 'La sangre reconoce a la sangre. Tu furia de dragón ya es tuya.', reward: { xp: 300, learn: 'furia_dragon' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_gnomo', race: 'gnomo', minLevel: 9, giver: 'npc_maestra_gnomo', title: 'Chispa en la botella', offer: 'Necesito estudiar elementales arcanos para mi tormenta. En las Ruinas Perdidas hay: derrotá a dos y contame cómo chisporrotean.', text: 'Fizzi quiere que derrotes a dos elementales arcanos en las Ruinas Perdidas.', objectives: [{ type: 'kill', enemy: 'elem_arcano', count: 2, text: 'Derrotá elementales arcanos' }], done: '¡Eso! Con eso cierro el circuito. Tu tormenta conductora está lista.', reward: { xp: 300, learn: 'tormenta_conductora' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_robot', race: 'robot', minLevel: 9, giver: 'npc_maestro_robot', title: 'Calibración', offer: 'PROTOCOLO DE ASALTO: NECESITA CALIBRACIÓN. Objetivo: dos gólems de lava en el Volcán. Calor alto. Proceder.', text: 'La Unidad K-7 quiere que derrotes a dos gólems de lava en el Volcán.', objectives: [{ type: 'kill', enemy: 'golem_lava', count: 2, text: 'Derrotá gólems de lava' }], done: 'CALIBRACIÓN COMPLETA. Protocolo de asalto instalado.', reward: { xp: 300, learn: 'protocolo_asalto' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_orco', race: 'orco', minLevel: 9, giver: 'npc_maestro_orco', title: 'Sangre de guerrero', offer: 'La horda no para por nada. Andá a cazar mantícoras (Cuevas Ancestrales o la Pradera de los Cíclopes): dos, y volvé con las colas si querés.', text: 'Grumak quiere que derrotes a dos mantícoras (Cuevas Ancestrales o Pradera de los Cíclopes).', objectives: [{ type: 'kill', enemy: 'manticora', count: 2, text: 'Derrotá mantícoras' }], done: '¡Eso es pelear! Ya sos una horda vos solo.', reward: { xp: 300, learn: 'horda_imparable' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_elfo', race: 'elfo', minLevel: 9, giver: 'npc_maestra_elfo', title: 'Luz en la cripta', offer: 'Los espectros le temen a la luna. Derrotá a tres (Bosque de los Susurros, Fortaleza Caída o Catacumbas) y vas a poder hacer llover su luz.', text: 'Ilyana quiere que derrotes a tres espectros (Bosque de los Susurros, Fortaleza Caída o Catacumbas).', objectives: [{ type: 'kill', enemy: 'espectro', count: 3, text: 'Derrotá espectros' }], done: 'La luna te vio pelear. Su lluvia es tuya.', reward: { xp: 300, learn: 'lluvia_lunar' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_alienigena', race: 'alienigena', minLevel: 9, giver: 'npc_maestro_alienigena', title: 'Señales del fondo', offer: 'Hay una mente enorme en el Abismo Marino: un calamar gigante. Su señal tapa la de tu nave. Derrotalo y vas a poder llamarla con fuerza.', text: 'Xo\'ren quiere que derrotes a un calamar gigante en el Abismo Marino.', objectives: [{ type: 'kill', enemy: 'calamar_gigante', count: 1, text: 'Derrotá a un calamar gigante' }], done: 'Silencio en el fondo del mar. Tu nave ahora te escucha clarito.', reward: { xp: 300, learn: 'senal_orbital' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_mediano', race: 'mediano', minLevel: 9, giver: 'npc_maestra_mediano', title: 'Probar la suerte', offer: 'Para que el destino te favorezca hay que tentarlo. Hay una quimera en la Pradera de los Cíclopes: tres cabezas, tres veces más suerte que necesitás. Derrotala.', text: 'La tía Pippa quiere que derrotes a una quimera en la Pradera de los Cíclopes.', objectives: [{ type: 'kill', enemy: 'quimera', count: 1, text: 'Derrotá a una quimera' }], done: '¿Viste? La suerte estaba de tu lado. Ahora el destino también.', reward: { xp: 300, learn: 'destino_favorable' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_vampiro', race: 'vampiro', minLevel: 9, giver: 'npc_maestra_vampiro', title: 'Sangre noble', offer: 'En el Jardín Carmesí vive una noble vampira que se cree mejor que nosotras. Derrotala y traeme el olor de su sangre en tu ropa.', text: 'Lady Morwen quiere que derrotes a una noble vampira en el Jardín Carmesí.', objectives: [{ type: 'kill', enemy: 'noble_vampira', count: 1, text: 'Derrotá a una noble vampira' }], done: 'Huele a sangre vieja. Bien. Ya podés llamar a la niebla.', reward: { xp: 300, learn: 'niebla_sangre' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_elfo_oscuro', race: 'elfo_oscuro', minLevel: 9, giver: 'npc_maestro_elfo_oscuro', title: 'Lo que vive en la oscuridad', offer: 'Allá abajo, en las Ruinas Perdidas, flota un contemplador. Mis ancestros le escapaban. Vos no: derrotalo.', text: 'Szarith quiere que derrotes a un contemplador en las Ruinas Perdidas.', objectives: [{ type: 'kill', enemy: 'contemplador', count: 1, text: 'Derrotá a un contemplador' }], done: 'El ojo se cerró. Ahora la oscuridad trabaja para vos.', reward: { xp: 300, learn: 'eclipse_arcano' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_infernal', race: 'infernal', minLevel: 9, giver: 'npc_maestra_infernal', title: 'Volver al fuego', offer: 'Volvé al Fondo del Volcán y derrotá a tres demonios menores. Que sepan quién manda en el fuego.', text: 'Ceniza quiere que derrotes a tres demonios menores en el Fondo del Volcán.', objectives: [{ type: 'kill', enemy: 'demonio_menor', count: 3, text: 'Derrotá demonios menores' }], done: 'Huelen a azufre tus botas. Perfecto: que llueva.', reward: { xp: 300, learn: 'lluvia_azufre' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_minotauro', race: 'minotauro', minLevel: 9, giver: 'npc_maestro_minotauro', title: 'Romper la línea', offer: 'Los centauros de la Pradera de los Cíclopes corren en fila. Cargá contra ellos: derrotá a tres.', text: 'Varg quiere que derrotes a tres centauros en la Pradera de los Cíclopes.', objectives: [{ type: 'kill', enemy: 'centauro', count: 3, text: 'Derrotá centauros' }], done: '¡Ni una fila en pie! Tus cuernos ya son una tormenta.', reward: { xp: 300, learn: 'tormenta_cuernos' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_hada', race: 'hada', minLevel: 9, giver: 'npc_maestra_hada', title: 'Malos sueños', offer: 'En el Bosque de los Sueños hay pesadillas que no dejan dormir a nadie. Derrotá a tres y te enseño a compartir un sueño lindo.', text: 'Brizna quiere que derrotes a tres pesadillas en el Bosque de los Sueños.', objectives: [{ type: 'kill', enemy: 'pesadilla', count: 3, text: 'Derrotá pesadillas' }], done: '¡Ahora sí se duerme bien! El sueño compartido es tuyo.', reward: { xp: 300, learn: 'sueno_compartido' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_driade', race: 'driade', minLevel: 9, giver: 'npc_maestra_driade', title: 'El jardín enfermo', offer: 'El Jardín Carmesí está enfermo de sangre. Derrotá a dos bestias de sangre y el bosque te va a prestar su fuerza.', text: 'Madre Sauce quiere que derrotes a dos bestias de sangre en el Jardín Carmesí.', objectives: [{ type: 'kill', enemy: 'bestia_sangre', count: 2, text: 'Derrotá bestias de sangre' }], done: 'El jardín respira de nuevo. El bosque despierta cuando lo llames.', reward: { xp: 300, learn: 'bosque_despierto' } },
    { school: true, turnIn: true, _source: 'v313', id: 'escuela_licantropo', race: 'licantropo', minLevel: 9, giver: 'npc_maestro_licantropo', title: 'Cazar al cazador', offer: 'Hay licántropos en el Bosque de los Susurros que no aceptan a ninguna manada. Cazá a dos y la luna te va a enseñar a saltar.', text: 'Fenrik quiere que derrotes a dos licántropos en el Bosque de los Susurros.', objectives: [{ type: 'kill', enemy: 'licantropo', count: 2, text: 'Derrotá licántropos' }], done: 'La luna te vio cazar. La cacería lunar es tuya.', reward: { xp: 300, learn: 'caceria_lunar' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_humano_17', race: 'humano', minLevel: 17, giver: 'npc_maestro_humano', title: 'Un duelo en el abismo', offer: 'Ya ganaste duelos. Ahora ganalos contra los mejores: en el Abismo de las Sombras hay caballeros que no conocen el miedo. Derrotá a dos.', text: 'Aldric quiere que derrotes a 2 caballeros del abismo (Abismo de las Sombras).', objectives: [{ type: 'kill', enemy: 'caballero_abismo', count: 2, text: 'Derrotá caballeros del abismo' }], done: 'Dos caballeros del abismo. Ya no peleás: dirigís el duelo.', reward: { xp: 2000, learn: 'maestria_duelo' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_elfo_17', race: 'elfo', minLevel: 17, giver: 'npc_maestra_elfo', title: 'Luz contra la pesadilla', offer: 'En el Linde del Sueño las pesadillas le tapan la luna a los que duermen. Derrotá a tres y la luna te va a bendecir a vos y a los tuyos.', text: 'Ilyana quiere que derrotes a 3 pesadillas esmeralda (Linde del Sueño).', objectives: [{ type: 'kill', enemy: 'pesadilla_esmeralda', count: 3, text: 'Derrotá pesadillas esmeralda' }], done: 'La luna volvió a brillar en el Linde. Su bendición es tuya.', reward: { xp: 2000, learn: 'bendicion_lunar' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_mediano_17', race: 'mediano', minLevel: 17, giver: 'npc_maestra_mediano', title: 'El acertijo de la esfinge', offer: 'Las esfinges de las Ruinas Celestes no pierden nunca un acertijo. Andá y ganale a una... aunque sea a los golpes. La suerte también es saber cuándo dejar de pensar.', text: 'La tía Pippa quiere que derrotes a una esfinge (Ruinas Celestes).', objectives: [{ type: 'kill', enemy: 'esfinge', count: 1, text: 'Derrotá a una esfinge' }], done: '¡Le ganaste a una esfinge! Eso es una racha de suerte de verdad.', reward: { xp: 2000, learn: 'racha_suerte' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_draconido_17', race: 'draconido', minLevel: 17, giver: 'npc_maestro_draconido', title: 'El llamado de los picos', offer: 'En los Picos del Dragón viven los dracónidos de élite: la guardia de los dragones viejos. Derrotá a dos y tu corazón va a latir como el de ellos.', text: 'Vharax quiere que derrotes a 2 dracónidos de élite (Picos del Dragón).', objectives: [{ type: 'kill', enemy: 'draconido_elite', count: 2, text: 'Derrotá dracónidos de élite' }], done: 'Ahora tu sangre arde como la de un dragón.', reward: { xp: 2000, learn: 'corazon_dragon' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_vampiro_17', race: 'vampiro', minLevel: 17, giver: 'npc_maestra_vampiro', title: 'Almas para la sed', offer: 'Los devoradores de almas del Abismo de las Sombras se creen los únicos que se alimentan de los demás. Demostrales lo contrario: dos.', text: 'Lady Morwen quiere que derrotes a 2 devoradores de almas (Abismo de las Sombras).', objectives: [{ type: 'kill', enemy: 'devorador_almas', count: 2, text: 'Derrotá devoradores de almas' }], done: 'Esa sed que sentís ya no se va. Bien: usala.', reward: { xp: 2000, learn: 'sed_insaciable' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_elfo_oscuro_17', race: 'elfo_oscuro', minLevel: 17, giver: 'npc_maestro_elfo_oscuro', title: 'Sombras más oscuras', offer: 'Hay sombras que caminan solas en el Abismo de las Sombras. Si podés apagar tres, la noche te va a obedecer.', text: 'Szarith quiere que derrotes a 3 sombras vivientes (Abismo de las Sombras).', objectives: [{ type: 'kill', enemy: 'sombra_viviente', count: 3, text: 'Derrotá sombras vivientes' }], done: 'La noche cerrada ya es tuya.', reward: { xp: 2000, learn: 'noche_cerrada' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_gnomo_17', race: 'gnomo', minLevel: 17, giver: 'npc_maestra_gnomo', title: 'Cristal conductor', offer: '¡Los gólems del Desierto de Cristal conducen la electricidad de una forma fascinante! Derrotá a dos y traeme los datos (o los pedazos).', text: 'Fizzi quiere que derrotes a 2 gólems de cristal (Desierto de Cristal).', objectives: [{ type: 'kill', enemy: 'golem_cristal', count: 2, text: 'Derrotá gólems de cristal' }], done: '¡Lo sabía! Con eso termino la red. ¡Es tuya!', reward: { xp: 2000, learn: 'red_electrica' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_alienigena_17', race: 'alienigena', minLevel: 17, giver: 'npc_maestro_alienigena', title: 'El gusano del desierto', offer: 'Un gran gusano de cristal hace vibrar todo el desierto: su ruido no me deja oír a la nave. Derrotalo y vas a poder plegar el aire como quieras.', text: 'Xo\'ren quiere que derrotes a un gran gusano de cristal (Desierto de Cristal).', objectives: [{ type: 'kill', enemy: 'gusano_cristal', count: 1, text: 'Derrotá a un gran gusano de cristal' }], done: 'Silencio. Ahora la gravedad te escucha.', reward: { xp: 2000, learn: 'colapso_gravitatorio' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_infernal_17', race: 'infernal', minLevel: 17, giver: 'npc_maestra_infernal', title: 'Fuego contra sombra', offer: 'En el Abismo de las Sombras hay engendros que se creen demonios. Mostrales qué es el fuego de verdad: dos.', text: 'Ceniza quiere que derrotes a 2 engendros de las sombras (Abismo de las Sombras).', objectives: [{ type: 'kill', enemy: 'demonio_sombras', count: 2, text: 'Derrotá engendros de las sombras' }], done: 'Ardieron. Ahora sabés desatar el infierno.', reward: { xp: 2000, learn: 'infierno_desatado' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_angel_17', race: 'angel', minLevel: 17, giver: 'npc_maestra_angel', title: 'Los que cayeron', offer: 'En las Ruinas Celestes hay ángeles que se olvidaron de cuidar a nadie. Duele, pero hay que detenerlos: dos.', text: 'Sor Celestine quiere que derrotes a 2 ángeles caídos (Ruinas Celestes).', objectives: [{ type: 'kill', enemy: 'angel_caido', count: 2, text: 'Derrotá ángeles caídos' }], done: 'Descansan. Y vos aprendiste qué es la gracia.', reward: { xp: 2000, learn: 'gracia_divina' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_hada_17', race: 'hada', minLevel: 17, giver: 'npc_maestra_hada', title: 'Hadas con pesadillas', offer: 'Unas primas mías se quedaron atrapadas en una pesadilla, en el Linde del Sueño. Despertalas a los golpes, ¡son tres!', text: 'Brizna quiere que derrotes a 3 hadas de la pesadilla (Linde del Sueño).', objectives: [{ type: 'kill', enemy: 'hada_pesadilla', count: 3, text: 'Derrotá hadas de la pesadilla' }], done: '¡Despertaron! Te enseñaron su danza para agradecerte.', reward: { xp: 2000, learn: 'danza_hadas' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_driade_17', race: 'driade', minLevel: 17, giver: 'npc_maestra_driade', title: 'El árbol que sueña', offer: 'En el Linde del Sueño hay árboles que sueñan pesadillas y lastiman a todos. Liberá a dos y su savia va a correr por vos.', text: 'Madre Sauce quiere que derrotes a 2 árboles soñadores (Linde del Sueño).', objectives: [{ type: 'kill', enemy: 'arbol_sonador', count: 2, text: 'Derrotá árboles soñadores' }], done: 'Ahora duermen tranquilos. Su savia es tuya.', reward: { xp: 2000, learn: 'savia_vital' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_enano_17', race: 'enano', minLevel: 17, giver: 'npc_maestro_enano', title: 'Más duro que la piedra', offer: 'Dicen que en el Desierto de Cristal hay gólems más duros que la piedra. Ningún enano se lo cree. Andá y probá que tienen razón... o no. Dos.', text: 'Borin quiere que derrotes a 2 gólems de cristal (Desierto de Cristal).', objectives: [{ type: 'kill', enemy: 'golem_cristal', count: 2, text: 'Derrotá gólems de cristal' }], done: 'Más duros que la piedra, decían. Ja. Hacé tu juramento.', reward: { xp: 2000, learn: 'juramento_piedra' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_orco_17', race: 'orco', minLevel: 17, giver: 'npc_maestro_orco', title: 'La gran cacería', offer: 'En la Cumbre del Mundo hay pájaros tan grandes que se llevan a un ogro. ¡Bajá a dos y vas a tener sed de batalla para siempre!', text: 'Grumak quiere que derrotes a 2 rocs (Cumbre del Mundo).', objectives: [{ type: 'kill', enemy: 'roc', count: 2, text: 'Derrotá rocs' }], done: '¡Dos rocs! La horda va a cantar esto por años.', reward: { xp: 2000, learn: 'sed_batalla' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_robot_17', race: 'robot', minLevel: 17, giver: 'npc_maestro_robot', title: 'Prueba de resistencia', offer: 'PRUEBA DE RESISTENCIA: blindaje reactivo pendiente. Objetivo: dos gólems de cristal, Desierto de Cristal. Proceder.', text: 'La Unidad K-7 quiere que derrotes a 2 gólems de cristal (Desierto de Cristal).', objectives: [{ type: 'kill', enemy: 'golem_cristal', count: 2, text: 'Derrotá gólems de cristal' }], done: 'PRUEBA SUPERADA. Blindaje reactivo instalado.', reward: { xp: 2000, learn: 'blindaje_reactivo' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_goliat_17', race: 'goliat', minLevel: 17, giver: 'npc_maestra_goliat', title: 'El titán del cielo', offer: 'En la Cumbre del Mundo camina un titán celeste. Es más grande que vos. Por eso tenés que ganarle.', text: 'Kaya quiere que derrotes a un titán celeste (Cumbre del Mundo).', objectives: [{ type: 'kill', enemy: 'titan_celeste', count: 1, text: 'Derrotá a un titán celeste' }], done: 'Le ganaste a un titán. La fuerza de la montaña ya es tuya.', reward: { xp: 2000, learn: 'fuerza_montana' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_minotauro_17', race: 'minotauro', minLevel: 17, giver: 'npc_maestro_minotauro', title: 'Cuernos contra escamas', offer: 'En los Picos del Dragón vuelan guivernos que nunca tocaron el suelo. Bajalos de una embestida: dos.', text: 'Varg quiere que derrotes a 2 guivernos ancestrales (Picos del Dragón).', objectives: [{ type: 'kill', enemy: 'guiverno_ancestral', count: 2, text: 'Derrotá guivernos ancestrales' }], done: 'Bien. Ahora la furia del laberinto te sigue a todos lados.', reward: { xp: 2000, learn: 'furia_laberinto' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_licantropo_17', race: 'licantropo', minLevel: 17, giver: 'npc_maestro_licantropo', title: 'Cazar una tormenta', offer: 'La manada caza lo que se mueve. Un dragón de la tormenta se mueve mucho. Cazalo y la manada te va a seguir.', text: 'Fenrik quiere que derrotes a un dragón de la tormenta (Picos del Dragón o Cumbre del Mundo).', objectives: [{ type: 'kill', enemy: 'dragon_tormenta', count: 1, text: 'Derrotá a un dragón de la tormenta' }], done: 'La manada ya te reconoce. Cuando aulles, va a venir.', reward: { xp: 2000, learn: 'llamado_manada' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_humano_25', race: 'humano', minLevel: 25, giver: 'npc_maestro_humano', title: 'El último duelo', offer: 'Te queda un rival: el más orgulloso de todos. Vive en la Ciudad de Dite y se cree invencible. Derrotalo y no te voy a poder enseñar nada más.', text: 'Aldric quiere que derrotes a un pecado de la soberbia (Ciudad de Dite).', objectives: [{ type: 'kill', enemy: 'pecado_soberbia', count: 1, text: 'Derrotá al Pecado de la soberbia' }], done: 'Ya no sos mi alumno. Sos un avatar de la magia de los humanos.', reward: { xp: 5000, learn: 'avatar_arcano' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_elfo_25', race: 'elfo', minLevel: 25, giver: 'npc_maestra_elfo', title: 'La luz más alta', offer: 'En el Empíreo arden los serafines: la única luz más alta que la luna. Enfrentá a uno... a flechazos. Si ganás, la luna va a quedarse con vos para siempre.', text: 'Ilyana quiere que derrotes a un serafín (El Empíreo).', objectives: [{ type: 'kill', enemy: 'serafin', count: 1, text: 'Derrotá a un serafín' }], done: 'La luna eterna te acompaña. No hay nada más que pueda enseñarte.', reward: { xp: 5000, learn: 'luna_eterna' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_mediano_25', race: 'mediano', minLevel: 25, giver: 'npc_maestra_mediano', title: 'Todo o nada', offer: 'La avaricia es la peor enemiga de la suerte. En el Círculo de los Pecados hay dos que se creen dueñas de toda la fortuna del mundo. Demostrales que no.', text: 'La tía Pippa quiere que derrotes a 2 pecados de la avaricia (Círculo de los Pecados).', objectives: [{ type: 'kill', enemy: 'pecado_avaricia', count: 2, text: 'Derrotá pecados de la avaricia' }], done: '¡Todo! Ahora la gran fortuna es de tu familia entera.', reward: { xp: 5000, learn: 'gran_fortuna' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_draconido_25', race: 'draconido', minLevel: 25, giver: 'npc_maestro_draconido', title: 'La ira del dragón', offer: 'Hay una ira más vieja que los dragones en la Ciudad de Dite. Derrotá a dos pecados de la ira y vas a poder ser dragón de verdad.', text: 'Vharax quiere que derrotes a 2 pecados de la ira (Ciudad de Dite).', objectives: [{ type: 'kill', enemy: 'pecado_ira', count: 2, text: 'Derrotá pecados de la ira' }], done: 'Ya no hace falta que te lo diga: sos un dragón.', reward: { xp: 5000, learn: 'forma_dragon' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_vampiro_25', race: 'vampiro', minLevel: 25, giver: 'npc_maestra_vampiro', title: 'Dueña de la noche', offer: 'Solo una criatura en el mundo encanta mejor que nosotras: el Pecado de la lujuria. Derrotala y la noche va a ser tuya.', text: 'Lady Morwen quiere que derrotes a un pecado de la lujuria (Círculo de los Pecados o Ciudad de Dite).', objectives: [{ type: 'kill', enemy: 'pecado_lujuria', count: 1, text: 'Derrotá al Pecado de la lujuria' }], done: 'La noche te pertenece. Yo ya no tengo nada que enseñarte.', reward: { xp: 5000, learn: 'senor_noche' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_elfo_oscuro_25', race: 'elfo_oscuro', minLevel: 25, giver: 'npc_maestro_elfo_oscuro', title: 'Envidia de la sombra', offer: 'Dos pecados de la envidia, en el Círculo de los Pecados, quieren lo que vos tenés: tu sombra. Apagalos.', text: 'Szarith quiere que derrotes a 2 pecados de la envidia (Círculo de los Pecados).', objectives: [{ type: 'kill', enemy: 'pecado_envidia', count: 2, text: 'Derrotá pecados de la envidia' }], done: 'Ahora podés apagar el sol cuando quieras.', reward: { xp: 5000, learn: 'eclipse_total' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_gnomo_25', race: 'gnomo', minLevel: 25, giver: 'npc_maestra_gnomo', title: 'Ingeniería de otro mundo', offer: '¡En la Nave Nodriza hay robots centinela! ¡Con circuitos que nunca vi! Derrotá a dos y desarmamos todo para hacer la gran tormenta.', text: 'Fizzi quiere que derrotes a 2 robots centinela (La Nave Nodriza).', objectives: [{ type: 'kill', enemy: 'robot_centinela', count: 2, text: 'Derrotá robots centinela' }], done: '¡FUNCIONA! La gran tormenta gnoma es tuya. Y la patente, mía.', reward: { xp: 5000, learn: 'gran_tormenta' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_alienigena_25', race: 'alienigena', minLevel: 25, giver: 'npc_maestro_alienigena', title: 'Volver a la nave', offer: 'Hay una nave allá arriba que no es la tuya, y dos comandantes grises que dan las órdenes. Derrotalos y tu nave va a poder disparar con todo.', text: 'Xo\'ren quiere que derrotes a 2 comandantes grises (La Nave Nodriza).', objectives: [{ type: 'kill', enemy: 'comandante_gris', count: 2, text: 'Derrotá comandantes grises' }], done: 'Tu nave tiene vía libre. Que llueva el bombardeo.', reward: { xp: 5000, learn: 'bombardeo_orbital' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_infernal_25', race: 'infernal', minLevel: 25, giver: 'npc_maestra_infernal', title: 'Las puertas de Dite', offer: 'En la Ciudad de Dite la ira arde más que mi fuego. Eso no lo puedo permitir. Apagá a dos pecados de la ira con un fuego mayor.', text: 'Ceniza quiere que derrotes a 2 pecados de la ira (Ciudad de Dite).', objectives: [{ type: 'kill', enemy: 'pecado_ira', count: 2, text: 'Derrotá pecados de la ira' }], done: 'Ahora tu fuego es el más grande. Apocalipsis, se llama.', reward: { xp: 5000, learn: 'apocalipsis' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_angel_25', race: 'angel', minLevel: 25, giver: 'npc_maestra_angel', title: 'La caída del orgullo', offer: 'El orgullo fue lo que hizo caer a los primeros ángeles. Vive en la Ciudad de Dite. Derrotalo y el cielo va a intervenir cada vez que lo llames.', text: 'Sor Celestine quiere que derrotes a un pecado de la soberbia (Ciudad de Dite).', objectives: [{ type: 'kill', enemy: 'pecado_soberbia', count: 1, text: 'Derrotá al Pecado de la soberbia' }], done: 'El cielo te escucha. Cuidá a los tuyos.', reward: { xp: 5000, learn: 'intervencion_divina' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_hada_25', race: 'hada', minLevel: 25, giver: 'npc_maestra_hada', title: 'Dominar el sueño', offer: 'Las dominaciones de los Salones de la Luz no duermen nunca. ¡Nunca! Eso es imposible. Derrotá a dos y te abro la puerta del reino de los sueños.', text: 'Brizna quiere que derrotes a 2 dominaciones (Salones de la Luz o El Empíreo).', objectives: [{ type: 'kill', enemy: 'dominacion', count: 2, text: 'Derrotá dominaciones' }], done: '¡Te doy la bienvenida al reino de los sueños! Ahora también es tuyo.', reward: { xp: 5000, learn: 'reino_suenos' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_driade_25', race: 'driade', minLevel: 25, giver: 'npc_maestra_driade', title: 'Raíces en la luna', offer: 'En la Luna Rota hay gusanos que se comen las raíces de todo lo que crece. Derrotá a dos y el corazón del bosque va a latir con vos.', text: 'Madre Sauce quiere que derrotes a 2 gusanos lunares (La Luna Rota).', objectives: [{ type: 'kill', enemy: 'gusano_lunar', count: 2, text: 'Derrotá gusanos lunares' }], done: 'El corazón del bosque late con el tuyo.', reward: { xp: 5000, learn: 'corazon_bosque' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_enano_25', race: 'enano', minLevel: 25, giver: 'npc_maestro_enano', title: 'La forja de las estrellas', offer: 'Dicen que en la Nave Nodriza hay guardianes de metal que ningún martillo rompe. Ningún martillo enano, dicen. Andá y mostrales. Dos.', text: 'Borin quiere que derrotes a 2 robots centinela (La Nave Nodriza).', objectives: [{ type: 'kill', enemy: 'robot_centinela', count: 2, text: 'Derrotá robots centinela' }], done: 'Ningún martillo, decían. Sos el rey bajo la montaña.', reward: { xp: 5000, learn: 'rey_montana' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_orco_25', race: 'orco', minLevel: 25, giver: 'npc_maestro_orco', title: 'La guerra de las estrellas', offer: 'En la Luna Rota hay cazadores que cruzaron las estrellas para pelear. ¡Por fin una pelea de verdad! Derrotá a tres y la horda te va a seguir a donde vayas.', text: 'Grumak quiere que derrotes a 3 cazadores estelares (La Luna Rota).', objectives: [{ type: 'kill', enemy: 'cazador_estelar', count: 3, text: 'Derrotá cazadores estelares' }], done: '¡CAUDILLO! La horda es tuya.', reward: { xp: 5000, learn: 'caudillo_guerra' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_robot_25', race: 'robot', minLevel: 25, giver: 'npc_maestro_robot', title: 'Protocolo final', offer: 'PROTOCOLO FINAL. Objetivo: dos comandantes grises, Nave Nodriza. Probabilidad de éxito: suficiente. Proceder.', text: 'La Unidad K-7 quiere que derrotes a 2 comandantes grises (La Nave Nodriza).', objectives: [{ type: 'kill', enemy: 'comandante_gris', count: 2, text: 'Derrotá comandantes grises' }], done: 'PROTOCOLO FINAL COMPLETO. Modo de guerra total: habilitado.', reward: { xp: 5000, learn: 'modo_guerra' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_goliat_25', race: 'goliat', minLevel: 25, giver: 'npc_maestra_goliat', title: 'Más alto que el cielo', offer: 'En el Empíreo vuelan querubines por encima de todo. Para hacer temblar el mundo tenés que bajar a dos.', text: 'Kaya quiere que derrotes a 2 querubines (El Empíreo).', objectives: [{ type: 'kill', enemy: 'querubin', count: 2, text: 'Derrotá querubines' }], done: 'Cuando golpees el suelo, va a temblar el mundo entero.', reward: { xp: 5000, learn: 'terremoto' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_minotauro_25', race: 'minotauro', minLevel: 25, giver: 'npc_maestro_minotauro', title: 'La arena de Dite', offer: 'En la Ciudad de Dite hay una arena donde pelea la ira en persona. Ganá dos peleas ahí y no va a quedar laberinto que no sea tuyo.', text: 'Varg quiere que derrotes a 2 pecados de la ira (Ciudad de Dite).', objectives: [{ type: 'kill', enemy: 'pecado_ira', count: 2, text: 'Derrotá pecados de la ira' }], done: 'Rey del laberinto. Ya no tengo nada que enseñarte.', reward: { xp: 5000, learn: 'rey_laberinto' } },
    { school: true, turnIn: true, _source: 'v314', id: 'escuela_licantropo_25', race: 'licantropo', minLevel: 25, giver: 'npc_maestro_licantropo', title: 'La última cacería', offer: 'En el Río Estigia hay perros de tres cabezas que cuidan la puerta del infierno. Cazá a tres y vas a ser el alfa de cualquier manada.', text: 'Fenrik quiere que derrotes a 3 cancerberos (Río Estigia).', objectives: [{ type: 'kill', enemy: 'cancerbero', count: 3, text: 'Derrotá cancerberos' }], done: 'Sos el alfa. La manada entera aúlla con vos.', reward: { xp: 5000, learn: 'alfa_manada' } },
  ];
})(window.Aventurs);
